function scannerProduct(code){return Object.values(menuData).flat().find(item=>menuActive(item)&&item[5]===String(code).trim())}
function scanBarcode(code,add=true){
  const product=scannerProduct(code);
  if(!product){showToast(`Barcode ${String(code).trim()||'-'} tidak ditemukan di Master Produk`);return false}
  if(add)addToCart(product,1);
  return product;
}
