// Struk kasir: modal "Pembayaran berhasil" setelah bayar + cetak struk roll thermal 58 mm (#receiptPrint, body.print-receipt).
// `@page size` tidak menerima tinggi auto, jadi fitReceiptPage() mengukur struk dan menulis @page receipt selebar 58 mm setinggi isinya.
let trxSeq=1088;const nextTrx=()=>`TRX-0920-${trxSeq++}`,nowHM=()=>{const d=new Date();return `${String(d.getHours()).padStart(2,'0')}.${String(d.getMinutes()).padStart(2,'0')}`},rcNum=n=>Math.round(n).toLocaleString('id-ID');
function receiptHtml(r){const o=r.order,row=(a,b,c='')=>`<div class="rc-row${c}"><span>${a}</span><span>${b}</span></div>`;return `<div class="receipt"><header><b class="rc-logo">RBT</b><strong>SEKULAN RBT REST AREA 519A</strong><span>Sragen, Jawa Tengah</span><span>Struk pembayaran</span></header><div class="rc-meta">${row(r.no,'')}${row(`20/09/2026 ${r.time}`,r.cashier)}${o?row(`${o.id} • ${o.customer}`,''):''}</div><div class="rc-items">${r.items.map(x=>`<div class="rc-item"><span>${x.name}</span>${row(`${x.qty} x ${rcNum(x.price)}`,rcNum(x.price*x.qty))}</div>`).join('')}</div><div class="rc-sum">${o?row('Total pesanan',rcNum(o.total))+row('Sudah dibayar',rcNum(o.paidBefore))+row(`Bayar sekarang (${r.method})`,r.method==='Free'?'FREE':rcNum(o.paidNow),' rc-strong')+row('Sisa tagihan',rcNum(o.rest)):row('TOTAL',rcNum(r.total),' rc-strong')+row('Pembayaran',r.method)}</div>${r.method==='Free'?'<div class="rc-free">FREE — tidak masuk penjualan<br>Persediaan tetap berkurang</div>':''}<footer>Terima kasih</footer></div>`}
function fitReceiptPage(){const h=$('#receiptPrint'),st=$('#receiptPage')||document.head.appendChild(Object.assign(document.createElement('style'),{id:'receiptPage'}));h.style.cssText='display:block;position:absolute;left:-9999px';const mm=Math.ceil(h.offsetHeight*25.4/96)+2;h.style.cssText='';st.textContent=`@page receipt{size:58mm ${mm}mm;margin:0}`}
function printReceipt(r){$('#receiptPrint').innerHTML=receiptHtml(r);fitReceiptPage();document.body.classList.add('print-receipt');window.print();document.body.classList.remove('print-receipt')}
function openReceiptModal(r){const o=r.order;openModal(`<div class="receipt-done"><span class="done-mark">✓</span><h2>Pembayaran berhasil</h2><p>${r.no} • 20 Sep 2026 ${r.time}${o?`<br>${o.id} • ${o.customer}`:''}</p><div class="done-amount">${r.shown}</div><div class="done-lines"><div><span>${o?'Dibayar sekarang':'Total transaksi'}</span><strong>${r.shown}</strong></div><div><span>Metode pembayaran</span><strong>${r.method}</strong></div>${o?`<div><span>Sisa tagihan</span><strong>${rupiah(o.rest)}</strong></div>`:''}</div></div><div class="modal-actions"><button class="btn ghost" data-close>Selesai</button><button class="btn primary" id="printReceipt">Cetak struk</button></div>`);$('#printReceipt').onclick=()=>printReceipt(r)}

